import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"进阶组导览","description":"前沿边界的四张桥接卡：可解释性、推理与测试时计算、MoE 与新架构、多模态——只讲定位与决策影响，推导全部外包给 Learn LLM。","frontmatter":{"title":"进阶组导览","description":"前沿边界的四张桥接卡：可解释性、推理与测试时计算、MoE 与新架构、多模态——只讲定位与决策影响，推导全部外包给 Learn LLM。","domain":"tech","tags":["tech","advanced","bridge","navigation"],"navOrder":90,"topicId":"advanced-guide","layer":"9","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":[],"next":["interpretability","reasoning-ttc","moe-frontier","multimodal"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/09-advanced/index.md","filePath":"zh/tech/09-advanced/index.md","lastUpdated":1791118227000}'),d={name:"zh/tech/09-advanced/index.md"};function o(i,t,l,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="进阶组导览" tabindex="-1">进阶组导览 <a class="header-anchor" href="#进阶组导览" aria-label="Permalink to &quot;进阶组导览&quot;">​</a></h1><blockquote><p><strong>所在组</strong>：进阶（Advanced · 桥接组） ｜ <strong>上一组出口</strong>：能用发布门与版本化纪律长期运行 ｜ <strong>本组出口</strong>：知道每个前沿主题影响哪个工程决策、何时跳转 Learn LLM</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：本组四个主题都不是「要学会推导」的内容，而是「要有位置感」的内容——它们决定你选什么模型、预期什么延迟结构、为什么某类输出「思考」很久。每页都是桥接卡：解决什么问题 / 影响什么决策 / 何时跳转 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>。</p><table tabindex="0"><thead><tr><th>卡片</th><th>一句话定位</th><th>最影响你的</th></tr></thead><tbody><tr><td><a href="./interpretability.html">可解释性</a></td><td>模型为什么这样输出</td><td>调试预期、合规叙事</td></tr><tr><td><a href="./reasoning-ttc.html">推理 · 测试时计算</a></td><td>「想更久」是一种性能轴</td><td>延迟结构、计费、停止条件</td></tr><tr><td><a href="./moe-frontier.html">MoE / 前沿架构</a></td><td>稀疏与长上下文架构</td><td>模型选型与成本曲线</td></tr><tr><td><a href="./multimodal.html">多模态</a></td><td>跨模态输入输出</td><td>输入管道与产品形态</td></tr></tbody></table><p><strong>纳入门槛</strong>：本组只收「Learn LLM 深水区的桥接卡」，每卡必须有明确的工程决策影响；纯研究向内容不进本组，防止其垃圾桶化。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>不确定某个前沿词该不该关心 → 在上表找一行，读对应卡（每张 ≤130 行），再决定是否去 Learn LLM 深挖。附录侧的 <a href="./multimodal-vision-case.html">视觉能力案例</a> 是多模态卡的真实案例配对。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>本组不承担原理正文；所有推导以 Learn LLM 为 canonical owner。卡片内出现的任何机制名词只给一句定位。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>桥接卡的「开发」语义 = 决策影响表：每张卡明确列出「这个机制变化时，你要改什么」（模型选型 / 预算 / 停止条件 / 数据管道）。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>各卡资料库列一手源（论文 arXiv 号、官方说明）与 Learn LLM 对应章节方向；证据层级 legend 见 <a href="./../00-map/site-boundaries.html">站点边界</a>。</p>',14)])])}const b=a(d,[["render",o]]);export{f as __pageData,b as default};
